class AliasSafeMosesBackend(RouteFinderBackend):
    def profile(self):
        result = super().profile()
        result["checkpoint_loading"] = "Strict full-state loading; duplicate names are restored only from another checkpoint key referencing the identical registered parameter/buffer object. No random or substituted weights."
        return result

    def run(self, items):
        scale = sample_scale(self.problem, items[0])
        bucket = 50 if scale <= 75 else 100
        runner = self.pool.get(self.key, bucket)
        if bucket not in self.validated_buckets:
            checkpoint = torch.load(self.checkpoints[str(bucket)], map_location="cpu", weights_only=False)
            weights = {name[len("policy."):]: value for name, value in checkpoint["state_dict"].items()
                       if name.startswith("policy.")}
            if not weights:
                raise ValueError("The original checkpoint has no policy weights")
            restored = load_alias_complete_state(runner.policy, weights)
            if "B" in self.problem:
                from train_100k_routefinder import install_signed_demand_adapter
                install_signed_demand_adapter(runner.env)
            self.validated_buckets.add(bucket)
            print(f"ALIAS_CHECKPOINT_LOAD {self.problem}/{self.method} bucket={bucket} restored_duplicate_names={restored}", flush=True)
        return super().run(items)
